    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("उठतकच", "सगळ्यो तोखणाय अल्लाहाक आसा, ताणें आमकां मरण हाडल्या उपरांत आमकां जिवीत दिलें, आनी ताचे कडेन परत येवप आसा.", "न्हिदून उठतकच, अल्लाहाक उपकार मानपाक.", "पैगंबर सल्ल्याह अलियाह वसलमान जागतना हें पठण केलें-दिवसाची सुरवात उपकार मानून आनी परकाचें उगडास करून केली."),
        "dua_leaving_home" to DuaText("घरांतल्यान भायर सरतकच", "अल्लाहच्या नांवान हांव अल्लाहचेर भरवसो दवरता. अल्लाह सोडून कोणूच बळ वा शक्ती ना.", "घरा भायर सरतना, अल्लाहच्या राखणे खातीर.", "देवदूतांचें म्हणणें आसाः'तूं मार्गदर्शन मेळटा, तुजी जतनाय घेता आनी तुजी राखण जाता', आनी शयतान पयस वता."),
        "dua_anxiety_distress" to DuaText("हुस्को आनी दुख्ख हांचे पसून मेकळीक मेळची", "हे अल्लाह, हुस्को आनी दुख्ख, असहायताय आनी आळस, दुख्ख आनी भ्याडपण, रिणाच्या ओडल्यान आनी लोकांच्या बळार येवपा पसून हांव तुका आलाशिरो मागता.", "दुःखाच्या, हुस्को, रिणाचो भार आनी मानसीक त्रास हांच्या वेळार.", "पैगंबर सल्लल्लाह अलीह वस्लमान सदांच ही दुआ केली-दुख्ख, आळस आनी रिणाची चिंता हांचे पसून आलाशिरो."),
        "dua_sayyidul_istighfar" to DuaText("सय्यद अल-इस्टिघफर (माफीचो मुखेली)", "हे अल्लाह, तूं म्हजो प्रभू, तूंच तूं. तूंच सोडून कोणाकूय पुजा करपाचो अधिकार ना. तूंच म्हाका निर्माण केलो आनी हांव तुजो सेवक, आनी हांव तुजो करार पाळता आनी वचन दिता तें हांव शक्य तितलें पाळता. हांव जे पाप केलां ताचे पसून हांव तुजो आलाशिरो मागता. हांव म्हजेचेर तुजो उपकार मान्य करता आनी हांव म्हजें पाप मान्य करता, देखून म्हाका माफ कर, कारण तुज्या शिवाय कोणूच पाप माफ करिना.", "सकाळ आनी सांज-पैगंबर सल्ल्याह अलियाह वसलमान शिकयल्ल्या पश्चात्तापाची सगळ्यांत बरी दुआ.", "सांजवेळार निश्चीतपणान म्हणपी आनी त्या रातीक मरण पावपी कोणूय स्वर्गांत प्रवेश करतलो; सकाळीं म्हटल्यार तेंच लागू जाता."),
        "dua_parents" to DuaText("पालकांक विनवणी", "म्हज्या देवा, हांव ल्हान आसतना तांणी म्हाका वाडयल्लो तसो दोगांयचेर दया कर.", "आवय-बापाय खातीर कुराण दुआ-भुरगेपणांत तांच्या देखरेखीच्या बदलाक.", "अल्लाहान स्वता आमकां आमच्या आवय-बापायच्या हे दुआ करपाक आदेश दिलो."),
        "dua_entering_mosque" to DuaText("मशिदीत प्रवेश करप", "हे अल्लाह, म्हजे खातीर तुज्या दयेचीं दारां उक्तीं कर.", "उजवो पांय घेवन मशिदीत पावलां मारतना.", "पैगंबर सल्ल्युल्लाह अलीह वस्लमान मशिदीत प्रवेश करपा खातीर ही दुआ शिकयली."),
        "dua_morning_asbahna" to DuaText("सकाळचें उगडास", "आमी सकाळीं भितर सरलां आनी सगळें राज्य सकाळीं अल्लाहाकडेन गेलां. सगळ्यो तोखणाय अल्लाहाक आसा. फकत अल्लाह सोडून कोणाकूच तोखणाय करपाचो अधिकार ना, एकलो, भागीदार नासतना. प्रभुत्व ताचेंच आनी तोखणाय ताचोच, आनी तो सगळ्या गजालींचेर प्रभुत्व दवरपी.", "सकाळीं सुन्नत दुआ पठयतालो.", "अल्लाहचें सार्वभौमत्व आनी एकताय मान्य करून ह्या दिवसाची सुरवात जाता."),
        "dua_evening_amsayna" to DuaText("सांज याद", "आमी सांजवेळार प्रवेश केला आनी पुराय राज्य अल्लाहचे शामेक प्रवेश केला. सगळ्यो तोखणाय अल्लाहाक आसा. फकत अल्लाह सोडून, एकलो, भागीदार नासतना कुणाचीय पुजा करपाचो अधिकार ना. राज्य त्याचाक आसा आनी तोखणाय ताचेच आसा, आनी तो सगळ्या गजालींचेर सामर्थ्यवान आसा.", "सांजवेळार सुन्नत दुआ पठण केलें.", "अल्लाहचें सार्वभौमत्व आनी एकताय सिद्ध करून रात सुरू जाता."),
        "dua_bismillah_la_yadurru" to DuaText("सगळ्या लुकसाणां पसून राखण", "अल्लाहच्या नांवान, जाच्या नांवान धर्तरेचेर वा स्वर्गांत कांयच लुकसाण करूंक शकना, आनी तो सगळो आयकपी, सर्वज्ञ आसा.", "सकाळीं आनी सांजीं तीन फावटीं.", "जो सकाळीं आनी सांजीं तीन फावटीं म्हणटलो, ताका कांयच लुकसाण जायना."),
        "dua_raditu_billahi" to DuaText("अल्लाहाक भगवान म्हूण समाधान", "म्हजो प्रभू म्हणून अल्लाह, इस्लाम हो म्हजो धर्म आनी म्हजो पैगंबर म्हणून मुहंमद सल्ल्याह मुस्लिमाचेर हांव खूश आसा.", "तीन फावटीं सकाळीं आनी सांजीं.", "निवाऱ्याच्या दिसा ताका प्रसन्न करपाचो अधिकार अल्लाहाक मेळटा."),
        "dua_hasbiyallah" to DuaText("हसबीअल्लाह (अल्लाह फावोसो आसा)", "म्हजे खातीर अल्लाह फावोसो आसा; ताचे भायर देव ना. हांव ताचेर भरवंसा दवरता, आनी तो पराक्रमी सिंहासनाचो स्वामी आसा.", "सात फावटीं सकाळीं आनी सांजीं.", "कुराणांतलें एक श्लोक; ह्या संवसारांतल्या आनी परतीच्या चिंतांआड अल्लाह फावोसो आसा."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("सुभानअल्लाही वा बिहामदीही", "अल्लाहाक महिमा आनी सगळी तोखणाय ताचीच.", "दिसाक शंबर फावटीं.", "दिसाक शंबर फावटीं म्हणपी ताच्या पापांची माफी मेळटा, जरी ते दर्याच्या फोम सारके आसलें तरी."),
        "dua_tahleel_100" to DuaText("ला इलाहा इल्लल्लाहु वाहदहू", "फकत अल्लाह सोडून कोणाकूच पुजा करपाचो हक्क ना, फकत एकलो, भागीदार नासतना. राजवट ताचीच आसा आनी तोखणाय ताचीच आसा, आनी तो सगळ्या गजालींचेर प्रभुत्व दवरपी आसा.", "दिसाक शंबर फावटीं म्हणप हो व्हड गुण.", "धा गुलामांक मुक्त करपाचें, बरयल्लीं शंबर बरी कामां, शंबर पापां मिटयिल्लीं आनी सांज मेरेन शयतनासावन राखण दिवपाचें इनाम."),
        "dua_leaving_mosque" to DuaText("मशिदी सोडून वचप", "हे अल्लाह, हांव तुज्या कृपेची मागता.", "दावो पांय घेवन मशिदी भायर सरतना.", "मशिदी भायर सरतना अल्लाहाकडेन उपकार आनी तरतूद मागप."),
        "dua_after_adhan" to DuaText("अधान उपरांत", "हे अल्लाह, ह्या परिपूर्ण आवाजाचो आनी स्थापीत जावंक लागपी प्रार्थनेचो स्वामी, मुहंमद सल्ल्याह अलियाह वसलम अल-वसीला आनी सद्गुण दिवचो, आनी ताका तूं वचन दिल्ल्या स्तराचेर उखल.", "अधान पुराय जाले उपरांत.", "कोण अशें म्हणटलो ताका न्यायाच्या दिसा पैगंबर सल्लल्लाह् अलैहि वसल्लमाचो मध्यस्थी मेळटलो."),
        "dua_after_salah_istighfar" to DuaText("फरद सलाह उपरांत", "हांव अल्लाहाक माफी मागता (3 फावटीं). हे अल्लाह, तूं सलाम आसा आनी तुजे कडल्यान शांती आसा. हे म्हान आनी सन्मान मेळोवपी तूं धन्य.", "सलामा उपरांत रोखडेंच.", "पैगंबर सल्ल्यल्लाह अल्लीह वसलमान दर एक सक्तीची प्रार्थना केल्या उपरांत हें पठण केलें."),
        "dua_after_salah_help_dhikr" to DuaText("तुजी याद दवरपाक म्हाका मदत कर.", "हे अल्लाह, तुजी याद दवरपाक, तुजी उपकार मानपाक आनी तुजी उत्तम रितीन पुजा करपाक म्हाका मदत कर.", "दर एका प्रार्थने उपरांत पैगंबर सल्ल्याह अलियाह वसलमान मुआद (रा.) हाका म्हणपाचो सल्लो दिलो.", "पैगंबर सल्ल्याह अलीह वसलमाचो एक खाशेलो सल्लो-उपासनेंत उत्कृष्टताय आनी सातत्य."),
        "dua_ayatul_kursi" to DuaText("सलाह उपरांत आयत अल-कुर्सी", "अल्लाह-ताचे भायर कोणूच देव ना, तो सदाक जिवीत, सगळ्यांचो पालन करपी. ताका न्हीद वा न्हीद येना. आकाशांत आनी धर्तरेचेर जें कितें आसा तें ताचेच मालकीचें. ताच्या परवानगीखाला ताचे कडेन कोण सिफ़ारिश करूंक शकता? ताचे मुखार कितें आसा आनी ताचे फाटलें कितें आसा तें ताका खबर आसा, आनी तो कितें सोदता ताचे भायर ताच्या गिन्यानांतल्यान कांयच तातूंत आसना. ताची कुर्शी आकाश आनी धर्तरेचेर पातळ्ळ्या, आनी तांची राखण करप ताका थकवचें ना. तो सर्वोच्च, महान.", "दर एक सक्तीची प्रार्थना केल्या उपरांत आनी न्हिदचे पयलीं.", "दर एका सक्तीच्या प्रार्थने उपरांत ताचो पठण करपी आनी न्हिदचे पयलीं पठण करपी, सकाळ मेरेन संरक्षण हाडपी स्वर्ग हांचे मदीं मरणा भायर कांयच उरना."),
        "dua_before_sleep" to DuaText("न्हिदचे पयलीं", "हे अल्लाह, तुज्या नांवान हांव मरता (न्हिदता) आनी हांव जगता (जागता).", "न्हिदल्या उपरांत.", "पैगंबर सल्ल्याह अलियाह वसलमान न्हिदचे पयलीं हें पठिल्लें."),
        "dua_sleep_tasbeeh" to DuaText("न्हिदचे पयलीं तसबीह-ए-फातीमी", "अल्लाहाक (33) गौरव असो, सगळ्यो तोखणाय अल्लाहाक (33), अल्लाह सगळ्यांत व्हड (34).", "न्हिदचे पयलीं-पैगंबर सल्ल्याह अलियाह वसलमान फातिमा आनी अली (रा.) हांकां तें शिकयलें.", "पैगंबर सल्ल्याह अलियाह वसलमान सांगलें की सेवक परस हें तुजे खातीर बरें."),
        "dua_sleep_qina_adhab" to DuaText("शिक्षे पसून राखण", "हे अल्लाह, तूं तुज्या सेवकांक परतून जिवंत करच्या दिसा तूं म्हाका ख्यास्त दिवचे पसून वाटाव.", "तीन फावटीं उजवो हात गालाखाला दवरात.", "न्हीद हें मरणाची याद करून आनी परकाळाची तयारी करून दिता."),
        "dua_bad_dream" to DuaText("वायट स्वप्ना उपरांत", "शापित शयताना कडल्यान हांव अल्लाहाक आलाशिरो मागता.", "वायट स्वप्ना उपरांतः तीन फावटीं दावे वटेन हळडुवें सुकून थुंको, मागीर दुसरे वटेन घुंवडाव.", "वायट सपन तुमकां लुकसाण करचें ना; कोणाकूच सांगचें न्हय."),
        "dua_yunus" to DuaText("पैगंबर युनूस (अ. स.) हाचो दुआ", "तूं सोडून देव ना. तो म्हान आसा. हांव अपराधी लोकां मदीं आसलो.", "पैगंबर युनूस (ए. एस.) हाचें दुआ व्हेलच्या पोटांत-दरेक कश्टा खातीर.", "खंयच्याय मुसलमान कोणूय गजालींत ही दुआ करता, तो अल्लाह ताका जाप दिता."),
        "dua_karb" to DuaText("दुःखाच्या वेळार दुआ (कार्ब)", "अल्लाह, सामर्थ्यवान, सहनशील हाचे भायर कोणाकूच पुजा करपाचो अधिकार ना. अल्लाह, सामर्थ्यवान सिंहासनाचो स्वामी हाचे भायर कोणाकूच पुजा करपाचो अधिकार ना. आकाशांचो स्वामी, धर्तऱ्याचो स्वामी आनी महान सिंहासनाचो स्वामी अल्लाह हाचे भायर कोणाचेंय पुजा करपाचो अधिकार ना.", "खर त्रास आनी कश्टाच्या वेळार.", "संकटाच्या वेळार पैगंबर सल्ल्याह अलियाह वसलमान हें पठिल्लें."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("या हयू या कयूम", "हे सदासर्वकाळ जगपी, हे सगळ्यांचे पालन करपी! तुज्या दयेन हांव मदत मागता.", "जेन्ना खंयचीय गजाल खूब जड जाता.", "जेन्ना जेन्ना पैगंबराक कितें तरी त्रास दितालो तेन्ना तो अशें म्हणटालो."),
        "dua_hasbunallah" to DuaText("हसबुनाल्लाहु वा निमाल वकील", "आमच्यासाठी अल्लाह फावोसो आसा आनी तो सगळ्यांत बरो कारभार करपी.", "दुस्मानाक भियेतना वा व्हड धोको येतना.", "पैगंबर इब्राहिम (अ. स.) हाणें उजो घाल्ल्यान हें सांगलें आनी पैगंबर सल्ल्याह अलियाह वसलमान धोक्याच्या वेळार अशें सांगलें."),
        "dua_entering_home" to DuaText("घरांत प्रवेश", "अल्लाहच्या नांवान.", "घरांत भितर सरतना अल्लांचें नांव सांगात आनी सलाम करून अभिवादन करात.", "जेन्ना भितर वचतना आनी जेवणा वेळार अल्लाहाक याद करतात, तेन्ना शयतान म्हणटाः हांगा रावपाक सुवात ना आनी रातचें जेवण ना."),
        "dua_travel" to DuaText("प्रवासा खातीर दुआ (सवारी)", "ज्या जाणें हें आमकां सोंपलां ताचो गौरव असो, आनी आमी स्वता हें करूंक शकले नात; आनी आमी निश्चीतपणान आमच्या प्रभू कडेन परत येतले.", "गाडयेचेर बसून तीन फावटीं अल्लाहू अकबर म्हणल्या उपरांत.", "सुन्नत प्रवास दुआ-राखण आनी आशीर्वाद मेळोवपा खातीर."),
        "dua_entering_market" to DuaText("बाजारांत प्रवेश", "अल्लाह सोडून कोणाकूय पुजा करपाचो अधिकार ना, एकलो, जोडीदार नासतना. ताचेंच राज्य आनी ताचीच तोखणाय. तो जिवीत दिता आनी मरण हाडटा, आनी तो सदाय जिवीत आसा आनी केन्नाच मरना. ताच्या हातांत सगळें बरें आसा, आनी ताका सगळ्या गजालींचेर सत्ता आसा.", "बाजारांत प्रवेश करतना.", "हदीसांत ताचे खातीर व्हड इनामाचो (लाखांनी बरे काम) उल्लेख आसा."),
        "dua_adam_forgiveness" to DuaText("पैगंबर आदामाचो दुआ (अ. स.)", "म्हज्या देवा, आमी स्वताचेर अन्याय केला, आनी तूं आम्हांक माफ केलो ना आनी आमचेर दया केली ना जाल्यार आमी निश्चीतच लुकसाण करपी लोकां मदीं आसतले.", "आदामाचो आनी हाववाचो (ए. एस.) पश्चात्तापाचो दुआ.", "मानवजातीचो पयलो पश्चात्ताप-अल्लाहान तो मान्य केलो."),
        "dua_abu_bakr" to DuaText("दुआ अबू बकराक (र.) शिकयतालो.", "हे अल्लाह, हांवें स्वताचेर खूब जुलूम केला, आनी तुज्या शिवाय कोणूच पापां माफ करिना, देखून म्हाका स्वता कडल्यान माफी दिवची आनी म्हजेचेर दया करची. खरें म्हणल्यार तूं क्षमा करपी, दयाळू.", "पैगंबर सल्ल्याह अलियाह वसलमान अबू बकर अस-सिद्दीक (रा.) हाका प्रार्थनेंत (ताशाहहुदा उपरांत) म्हणपाक शिकयलें.", "प्रार्थनेचे शेवटाक सुन्नत दुआ."),
        "dua_astaghfirullah_atubu" to DuaText("दिसपट्टो इस्तिघफर", "हांव अल्लाहाक क्षमा मागता आनी पश्चात्ताप करून ताचे कडेन वळटा.", "पैगंबर सल्ल्याह अलियाह वसलमान दिसाक सत्तर फावटीं परस चड वेळा माफी मागली.", "पैगंबर सलाईल्लाह अलीह वसलमान सांगलेंः हांव अल्लाहाक माफी मागता आनी दिसाक सत्तर फावटींपरस चड वेळा ताका पश्चात्ताप करता."),
        "dua_laylatul_qadr" to DuaText("दुआ फॉर लैलात अल-कदर", "हे अल्लाह, तूं परम क्षमाशील आनी तुका क्षमा करपाक आवडटा, देखून म्हाका क्षमा कर.", "लैलात अल-कदर खातीर आयशा (आर. ए.) हाका शिकयलें.", "रमजान आनी लैलात अल-कदर ह्या निमाण्या रातीं खातीर एक खाशेलो दुआ."),
        "dua_family_coolness" to DuaText("दोळ्यांची थंडसाण (जोडीदार आनी भुरगीं)", "म्हज्या देवा, आमच्या जोडीदारांक आनी आमच्या संततींकडल्यान आमकां आमच्या दोळ्यांची शीतलता दिवची, आनी आमकां नीतिमानांचें फुडारी करचें.", "धर्मीक जोडीदार आनी भुरग्यां खातीर कुराण दुआ.", "घरांत शांतताय आनी धर्मीक भुरग्यां खातीर."),
        "dua_righteous_children" to DuaText("धर्मीक भुरग्यां खातीर", "म्हज्या प्रभू, म्हाका तुजे कडल्यान शुद्ध संतती दिव. तूंच विनवणी आयकपी.", "पैगंबर ज़कारिया (अ. स.) हाचें दुआ.", "भुरगीं सोदपी लोकां खातीर कुराण दुआ."),
        "dua_ibrahim_prayer_family" to DuaText("प्रार्थनेचे संस्थापक", "म्हज्या प्रभू, म्हाका प्रार्थनेचो आनी म्हज्या संततीचो संस्थापक कर. म्हज्या प्रभू, म्हजी विनवणी मान्य कर. म्हज्या प्रभू, म्हाका, म्हज्या आवय-बापायक आनी विश्वास दवरप्यांक हिशेब थारपाच्या दिसा माफ कर.", "पैगंबर इब्राहिम (अ. स.) हाचें दुआ स्वता खातीर आनी ताच्या वंशजांक.", "सादारणपणान प्रार्थनेच्या शेवटाक पठण करतात."),
        "dua_newlywed" to DuaText("नवविवाहित जोडप्यांक तोखणाय", "अल्लाह तुका आशीर्वाद दिवचो, तुका आशीर्वाद दिवचो आनी तूं दोगूय बरेपणान एकठांय हाडचो.", "कोणाकूय तांच्या लग्नाचेर तोखणाय करतना.", "लग्ना खातीर सुन्नान तोखणाय करतात."),
        "dua_before_eating" to DuaText("जेवचे पयलीं", "अल्लाहच्या नांवान. (विसरल्यारः) अल्लाहच्या नांवान, ताच्या सुरवेक आनी शेवटाक.", "जेवचे पयलीं. विसरल्यार कांय प्रमाणांत सांग.", "बिस्मिल्लाह म्हणिल्ल्यान शायतानाक जेवण वांटपा पसून आडायता."),
        "dua_after_eating" to DuaText("जेवणा उपरांत", "सगळ्यो तोखणाय अल्लाहाक आसा, जाणें म्हाका हें पोसयलें आनी म्हजे वटेनच्यान कसलीच बळ वा शक्ती नासतना म्हाका तें दिलें.", "जेवण सोंपतकच.", "जे म्हणटा ताचे फाटल्या पापांची माफी मेळटा."),
        "dua_host" to DuaText("यजमानाक", "हे अल्लाह, तूं तांकां जें दिलें तातूंत तांकां आशीर्वाद दिवचो, तांकां माफ कर आनी तांचेचेर दया कर.", "यजमानाक, कोणाच्या तरी घरांत जेवल्यान.", "सुन्ना तरेन यजमानाक उपकार."),
    )
}
